python3 -c "
import sys
content = open('/app/output/final_report.html').read()

errors = []

# 1. Valid HTML structure
if not content.strip().startswith('<!DOCTYPE html>'): errors.append('Missing DOCTYPE')
if not content.strip().endswith('</html>'): errors.append('Missing closing </html>')
if content.count('<html') != content.count('</html>'): errors.append('Mismatched html tags')
if content.count('<body') != content.count('</body>'): errors.append('Mismatched body tags')
if content.count('<head>') != content.count('</head>'): errors.append('Mismatched head tags')

# 2. All required sections
required_sections = [
    'station-utilization',
    'queue-wait-analysis', 
    'energy-grid-load',
    'renewable-pricing',
    'vehicle-charging-behavior',
    'optimization-recommendations'
]
for sid in required_sections:
    if f'id=\"{sid}\"' not in content:
        errors.append(f'Missing section: {sid}')

# 3. KPI banner
if content.count('kpi-card') < 5:
    errors.append(f'Expected 5+ KPI cards, found {content.count(\"kpi-card\")}')

# 4. Charts embedded
chart_count = content.count('data:image/png;base64,')
if chart_count < 20:
    errors.append(f'Expected 20+ charts, found {chart_count}')

# 5. Navigation
if content.count('nav-bar') < 1:
    errors.append('Missing nav bar')

# 6. Check for common issues
if '{{' in content or '}}' in content:
    errors.append('Unrendered template variables')
if 'NaN' in content:
    errors.append('NaN values in HTML')

# 7. Check data note present
if 'Data note' not in content:
    errors.append('Missing data integrity note')

# 8. File size reasonable
size_mb = len(content) / (1024*1024)
if size_mb < 0.5:
    errors.append(f'Report suspiciously small: {size_mb:.1f}MB')
elif size_mb > 5:
    errors.append(f'Report too large: {size_mb:.1f}MB')

if errors:
    print('VALIDATION FAILED:')
    for e in errors:
        print(f'  - {e}')
    sys.exit(1)
else:
    print('VALIDATION PASSED')
    print(f'  Size: {size_mb:.2f} MB')
    print(f'  Charts: {chart_count}')
    print(f'  Sections: {len(required_sections)}')
    print(f'  KPI cards: {content.count(\"kpi-card\")}')
    print(f'  Data tables: {content.count(\"data-table\")}')
    print(f'  Recommendations: {content.count(\"rec-card\")}')
    print(f'  Insight boxes: {content.count(\"insight-box\")}')
"

